			dw kw_cpeqvv, var_draw_y0, var_draw_y
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero, tmp0, if180_1
			dw do178_e_go
if180_1:

